CREATE TABLE parent_student_links (id BIGINT PRIMARY KEY AUTO_INCREMENT, parent_id BIGINT NOT NULL, student_id BIGINT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_link_parent FOREIGN KEY(parent_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_link_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT uq_parent_student UNIQUE(parent_id,student_id), INDEX idx_link_student_status(student_id,status));
